def compute(vars):
    passenger_service_personnel = vars["v1"]
    total_employees = vars["v2"]

    if total_employees == 0:
        return None

    percentage = passenger_service_personnel / total_employees * 100
    return {
        "value": percentage,
        "trace": {
            "passenger_service_personnel": passenger_service_personnel,
            "total_employees": total_employees,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
